    "description": "Fetch detailed information for one or more Hugging Face repositories (model, dataset, or space). Returns metadata, dataset structure, or dataset row previews depending on the operations requested. Auto-detects repo type unless specified.\n\nUse `hub_repo_search` instead when you need to discover repos by query rather than look up known IDs.\n\nFor datasets, call with `operations: dataset_structure` first to discover configs, splits, sizes, and schema before calling `dataset_preview`. Only call `dataset_preview` directly if the dataset is known to have a single config/split.\n\nParameters:\n- repo_ids: One or more repository IDs (e.g., \"owner/repo-name\")\n- repo_type: One of \"model\", \"dataset\", \"space\" (auto-detected if omitted)\n- operations: One or more of \"overview\", \"dataset_structure\", \"dataset_preview\"\n- config: Dataset config name (required for dataset_preview when multiple configs exist)\n- split: Dataset split name (required for dataset_preview when multiple splits exist)\n- offset: Row offset for dataset_preview pagination\n- limit: Number of rows to return in dataset_preview",
    "inputSchema": {
      "$schema": "https://json-schema.org/draft/2020-12/schema",
      "properties": {
        "config": {
          "description": "Dataset Viewer config. Required for dataset_preview when the dataset has multiple config/split options. Discover via dataset_structure.",
          "type": "string"
        },
        "limit": {
          "description": "Row count for dataset_preview. Defaults to 5 and is clamped to 1-100.",
          "maximum": 9007199254740991,
          "minimum": -9007199254740991,
          "type": "integer"
        },
        "offset": {
          "description": "Row offset for dataset_preview. Defaults to 0.",
          "maximum": 9007199254740991,
          "minimum": 0,
          "type": "integer"
        },
        "operations": {
          "description": "Details to return. Defaults to [\"overview\"]. For datasets, prefer [\"overview\", \"dataset_structure\"] first; then call [\"dataset_preview\"] with config and split.",
          "items": {
            "enum": [
              "overview",
              "dataset_structure",
              "dataset_preview"
            ],
            "type": "string"
          },
          "type": "array"
        },
        "repo_ids": {
          "description": "Repo IDs for (models|dataset/space) - usually in author/name format (e.g. openai/gpt-oss-120b)",
          "items": {
            "minLength": 1,
            "type": "string"
          },
          "maxItems": 10,
          "minItems": 1,
          "type": "array"
        },
        "repo_type": {
          "description": "Specify lookup type; otherwise auto-detects",
          "enum": [
            "model",
            "dataset",
            "space"
          ],
          "type": "string"
        },
        "split": {
          "description": "Dataset Viewer split. Required for dataset_preview when the dataset has multiple config/split options. Discover via dataset_structure.",
          "type": "string"
        }
      },
      "required": [
        "repo_ids"
      ],
      "type": "object"
    },
    "name": "hf:hub_repo_details"
  },
  {
    "description": "Read details, comments, reviews, files changed, or other data from a specific pull request. Use list_pull_requests to browse PRs, or search_pull_requests for keyword search. Use issue_read for non-PR issues.\n\nParameters:\n- after: Cursor for pagination within the PR's sub-resources\n- method: What to retrieve — e.g., \"details\", \"comments\", \"reviews\", \"files\"\n- owner: Repository owner (user or org)\n- page: Page number\n- perPage: Results per page\n- pullNumber: Pull request number\n- repo: Repository name",
    "inputSchema": {
      "properties": {
        "after": {
          "description": "Cursor for pagination, used only by the get_review_comments method. Pass the endCursor from the previous page's PageInfo to fetch the next page.",
          "type": "string"
        },
        "method": {
          "description": "Action to specify what pull request data needs to be retrieved from GitHub. \nPossible options: \n 1. get - Get details of a specific pull request.\n 2. get_diff - Get the diff of a pull request.\n 3. get_status - Get combined commit status of a head commit in a pull request.\n 4. get_files - Get the list of files changed in a pull request. Use with pagination parameters to control the number of results returned.\n 5. get_commits - Get the list of commits on a pull request. Use with pagination parameters to control the number of results returned.\n 6. get_review_comments - Get review threads on a pull request. Each thread contains logically grouped review comments made on the same code location during pull request reviews. Returns threads with metadata (isResolved, isOutdated, isCollapsed) and their associated comments. Use cursor-based pagination (perPage, after) to control results.\n 7. get_reviews - Get the reviews on a pull request. When asked for review comments, use get_review_comments method. Use with pagination parameters to control the number of results returned.\n 8. get_comments - Get comments on a pull request. Use this if user doesn't specifically want review comments. Use with pagination parameters to control the number of results returned.\n 9. get_check_runs - Get check runs for the head commit of a pull request. Check runs are the individual CI/CD jobs and checks that run on the PR.\n",
          "enum": [
            "get",
            "get_diff",
            "get_status",
            "get_files",
            "get_commits",
            "get_review_comments",
            "get_reviews",
            "get_comments",
            "get_check_runs"
          ],
          "type": "string"
        },
        "owner": {
          "description": "Repository owner",
          "type": "string",
          "x-mcp-header": "owner"
        },
        "page": {
          "description": "Page number for pagination (min 1)",
          "minimum": 1,
          "type": "number"
        },
        "perPage": {
          "description": "Results per page for pagination (min 1, max 100)",
          "maximum": 100,
          "minimum": 1,
          "type": "number"
        },
        "pullNumber": {
          "description": "Pull request number",
          "type": "number"
        },
        "repo": {
          "description": "Repository name",
          "type": "string",
          "x-mcp-header": "repo"
        }
      },
      "required": [
        "method",
        "owner",
        "repo",
        "pullNumber"
      ],
      "type": "object"
    },
    "name": "github:pull_request_read"
  },
